CREATE OR REPLACE FUNCTION public.protect_profile_fields() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR public.is_admin() OR current_setting('app.bypass_profile_guard',true)='on' THEN RETURN NEW; END IF; NEW.balance:=OLD.balance; NEW.is_active:=OLD.is_active; NEW.id:=OLD.id; NEW.email:=OLD.email; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.protect_profile_fields() FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.package_stock(p_product_id uuid) RETURNS TABLE(package_id uuid,available bigint,sold bigint) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT pk.id,count(k.id) FILTER(WHERE NOT k.is_used),count(k.id) FILTER(WHERE k.is_used) FROM public.product_packages pk LEFT JOIN public.product_keys k ON k.package_id=pk.id WHERE pk.product_id=p_product_id AND(pk.is_active OR public.is_admin()) GROUP BY pk.id; $$;
REVOKE ALL ON FUNCTION public.package_stock(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.package_stock(uuid) TO anon,authenticated,service_role;
CREATE FUNCTION public.purchase_product(p_product_id uuid,p_quantity integer) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p record; pr record; k record; tot numeric(12,2); nb numeric(12,2); oid uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF; IF p_quantity<>1 THEN RAISE EXCEPTION 'Choose one key at a time'; END IF; SELECT * INTO p FROM public.products WHERE id=p_product_id AND is_active FOR UPDATE; IF p IS NULL THEN RAISE EXCEPTION 'Product unavailable'; END IF; SELECT * INTO pr FROM public.profiles WHERE id=auth.uid() FOR UPDATE; IF pr IS NULL OR NOT pr.is_active THEN RAISE EXCEPTION 'Account unavailable'; END IF; SELECT * INTO k FROM public.product_keys WHERE product_id=p.id AND package_id IS NULL AND NOT is_used ORDER BY created_at,id LIMIT 1 FOR UPDATE SKIP LOCKED; IF k IS NULL THEN RAISE EXCEPTION 'NO_KEYS'; END IF; tot:=coalesce(nullif(p.discount_price,0),p.price); IF tot<=0 THEN RAISE EXCEPTION 'Price not set'; END IF; IF pr.balance<tot THEN RAISE EXCEPTION 'INSUFFICIENT_BALANCE'; END IF; nb:=pr.balance-tot; PERFORM set_config('app.bypass_profile_guard','on',true); UPDATE public.profiles SET balance=nb WHERE id=auth.uid(); INSERT INTO public.orders(user_id,product_id,product_name,quantity,unit_price,total,status,delivered_key) VALUES(auth.uid(),p.id,p.name,1,tot,tot,'completed',k.key_value) RETURNING id INTO oid; UPDATE public.product_keys SET is_used=true,used_by=auth.uid(),order_id=oid,used_at=now() WHERE id=k.id; UPDATE public.products SET stock=(SELECT count(*) FROM public.product_keys WHERE product_id=p.id AND NOT is_used) WHERE id=p.id; INSERT INTO public.wallet_transactions(user_id,amount,type,description,balance_after) VALUES(auth.uid(),-tot,'purchase','Purchase: '||p.name,nb); RETURN oid; END; $$;
REVOKE ALL ON FUNCTION public.purchase_product(uuid,integer) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.purchase_product(uuid,integer) TO authenticated;
CREATE FUNCTION public.purchase_package(p_package_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE pk record;p record;pr record;k record;tot numeric(12,2);nb numeric(12,2);oid uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF; SELECT * INTO pk FROM public.product_packages WHERE id=p_package_id AND is_active FOR UPDATE; IF pk IS NULL THEN RAISE EXCEPTION 'Package unavailable'; END IF; SELECT * INTO p FROM public.products WHERE id=pk.product_id AND is_active; IF p IS NULL THEN RAISE EXCEPTION 'Product unavailable'; END IF; tot:=pk.price; IF tot<=0 THEN RAISE EXCEPTION 'Price not set'; END IF; SELECT * INTO pr FROM public.profiles WHERE id=auth.uid() FOR UPDATE; IF pr IS NULL OR NOT pr.is_active THEN RAISE EXCEPTION 'Account unavailable'; END IF; SELECT * INTO k FROM public.product_keys WHERE package_id=pk.id AND NOT is_used ORDER BY created_at,id LIMIT 1 FOR UPDATE SKIP LOCKED; IF k IS NULL THEN RAISE EXCEPTION 'NO_KEYS'; END IF; IF pr.balance<tot THEN RAISE EXCEPTION 'INSUFFICIENT_BALANCE'; END IF; nb:=pr.balance-tot; PERFORM set_config('app.bypass_profile_guard','on',true); UPDATE public.profiles SET balance=nb WHERE id=auth.uid(); INSERT INTO public.orders(user_id,product_id,product_name,quantity,unit_price,total,status,delivered_key,package_id,package_name) VALUES(auth.uid(),p.id,p.name||' — '||pk.name,1,tot,tot,'completed',k.key_value,pk.id,pk.name) RETURNING id INTO oid; UPDATE public.product_keys SET is_used=true,used_by=auth.uid(),order_id=oid,used_at=now() WHERE id=k.id; UPDATE public.products SET stock=(SELECT count(*) FROM public.product_keys WHERE product_id=p.id AND NOT is_used) WHERE id=p.id; INSERT INTO public.wallet_transactions(user_id,amount,type,description,balance_after) VALUES(auth.uid(),-tot,'purchase','Purchase: '||p.name||' — '||pk.name,nb); RETURN oid; END; $$;
REVOKE ALL ON FUNCTION public.purchase_package(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.purchase_package(uuid) TO authenticated;
CREATE FUNCTION public.admin_adjust_balance(p_user_id uuid,p_amount numeric,p_description text,p_type text DEFAULT 'admin_adjustment') RETURNS numeric LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE nb numeric(12,2); BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Forbidden'; END IF; IF p_amount IS NULL OR p_amount=0 THEN RAISE EXCEPTION 'Invalid amount'; END IF; UPDATE public.profiles SET balance=balance+p_amount WHERE id=p_user_id RETURNING balance INTO nb; IF nb IS NULL THEN RAISE EXCEPTION 'User not found'; END IF; INSERT INTO public.wallet_transactions(user_id,amount,type,description,balance_after) VALUES(p_user_id,p_amount,coalesce(p_type,'admin_adjustment'),p_description,nb); RETURN nb; END; $$;
REVOKE ALL ON FUNCTION public.admin_adjust_balance(uuid,numeric,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_adjust_balance(uuid,numeric,text,text) TO authenticated;
CREATE FUNCTION public.admin_refund_order(p_order_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o record;nb numeric(12,2); BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Forbidden'; END IF; SELECT * INTO o FROM public.orders WHERE id=p_order_id FOR UPDATE; IF o IS NULL THEN RAISE EXCEPTION 'Order not found'; END IF; IF o.status='refunded' THEN RAISE EXCEPTION 'Already refunded'; END IF; UPDATE public.profiles SET balance=balance+o.total WHERE id=o.user_id RETURNING balance INTO nb; INSERT INTO public.wallet_transactions(user_id,amount,type,description,balance_after) VALUES(o.user_id,o.total,'refund','Refund: '||o.product_name,nb); UPDATE public.orders SET status='refunded' WHERE id=p_order_id; END; $$;
REVOKE ALL ON FUNCTION public.admin_refund_order(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_refund_order(uuid) TO authenticated;
CREATE FUNCTION public.admin_stats() RETURNS json LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Forbidden'; END IF; RETURN json_build_object('total_users',(SELECT count(*) FROM public.profiles),'total_products',(SELECT count(*) FROM public.products),'total_orders',(SELECT count(*) FROM public.orders),'pending_orders',(SELECT count(*) FROM public.orders WHERE status='pending'),'completed_orders',(SELECT count(*) FROM public.orders WHERE status='completed'),'total_sales',(SELECT coalesce(sum(total),0) FROM public.orders WHERE status NOT IN('refunded','cancelled')),'total_balance',(SELECT coalesce(sum(balance),0) FROM public.profiles)); END; $$;
REVOKE ALL ON FUNCTION public.admin_stats() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_stats() TO authenticated;
CREATE FUNCTION public.verify_payment(p_method text,p_amount numeric,p_trx text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t record;nb numeric(12,2);clean text:=upper(trim(p_trx)); BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF; IF NOT EXISTS(SELECT 1 FROM public.site_settings WHERE key='manual_payment_enabled' AND value='true') THEN RETURN 'DISABLED'; END IF; IF clean='' OR length(clean)>64 OR p_amount IS NULL OR p_amount<=0 OR p_method NOT IN('bkash','nagad') THEN RETURN 'INVALID'; END IF; SELECT * INTO t FROM public.accepted_trx WHERE upper(trim(trx_id))=clean FOR UPDATE; IF t IS NULL OR t.status='disabled' THEN INSERT INTO public.payments(user_id,amount,method,trx_id,status) VALUES(auth.uid(),p_amount,p_method,clean,'invalid'); RETURN 'INVALID'; END IF; IF t.status='used' THEN IF t.used_by=auth.uid() AND t.method=p_method AND t.amount=p_amount THEN RETURN 'ALREADY'; END IF; RETURN 'USED'; END IF; IF t.method<>p_method OR t.amount<>p_amount THEN RETURN 'INVALID'; END IF; PERFORM set_config('app.bypass_profile_guard','on',true); UPDATE public.profiles SET balance=balance+t.amount WHERE id=auth.uid() AND is_active RETURNING balance INTO nb; IF nb IS NULL THEN RAISE EXCEPTION 'Account unavailable'; END IF; UPDATE public.accepted_trx SET status='used',used_by=auth.uid(),used_at=now() WHERE id=t.id; INSERT INTO public.wallet_transactions(user_id,amount,type,description,balance_after) VALUES(auth.uid(),t.amount,'deposit','Deposit via '||p_method||' ('||clean||')',nb); INSERT INTO public.payments(user_id,amount,method,trx_id,status) VALUES(auth.uid(),t.amount,p_method,clean,'completed'); RETURN 'OK'; END; $$;
REVOKE ALL ON FUNCTION public.verify_payment(text,numeric,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.verify_payment(text,numeric,text) TO authenticated;
CREATE FUNCTION public.credit_uddoktapay_payment(p_invoice_id text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p record;nb numeric(12,2); BEGIN SELECT * INTO p FROM public.uddoktapay_payments WHERE invoice_id=p_invoice_id FOR UPDATE; IF p IS NULL THEN RETURN 'NOT_FOUND'; END IF; IF p.status='completed' THEN RETURN 'ALREADY'; END IF; IF p.status<>'verified' THEN RETURN 'NOT_VERIFIED'; END IF; PERFORM set_config('app.bypass_profile_guard','on',true); UPDATE public.profiles SET balance=balance+p.amount WHERE id=p.user_id RETURNING balance INTO nb; IF nb IS NULL THEN RAISE EXCEPTION 'Profile missing'; END IF; UPDATE public.uddoktapay_payments SET status='completed',credited_at=now() WHERE id=p.id; INSERT INTO public.wallet_transactions(user_id,amount,type,description,balance_after) VALUES(p.user_id,p.amount,'deposit','Deposit via UddoktaPay ('||p.invoice_id||')',nb); INSERT INTO public.payments(user_id,amount,method,trx_id,status) VALUES(p.user_id,p.amount,'uddoktapay',p.invoice_id,'completed'); RETURN 'OK'; END; $$;
REVOKE ALL ON FUNCTION public.credit_uddoktapay_payment(text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.credit_uddoktapay_payment(text) TO service_role;